            cin >> D[i][j];
        }
    }

    // We'll simulate the reverse process:
    // For each possible start and end, check if it's possible.
    // Since constraints are small (likely H,W <= 50 or so), brute force is fine.

    // Directions: 8 neighbors
    int dr[8] = {-1,-1,-1,0,0,1,1,1};
    int dc[8] = {-1,0,1,-1,1,-1,0,1};

    // Function to apply damage forward from a path
    auto simulate = [&](int si, int sj, int ti, int tj) -> bool {
        vector<vector<int>> cur(H, vector<int>(W, 0));
        int ci = si, cj = sj;
        // We must move from start to end in a sequence of steps
        // The path length = max(|ti-si|, |tj-sj|) because king moves
        int steps = max(abs(ti - si), abs(tj - sj));
        if (steps == 0) {
            // start == end, just apply once
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int ni = ci + di, nj = cj + dj;
                    if (ni >= 0 && ni < H && nj >= 0 && nj < W) {
                        cur[ni][nj]++;
                    }
                }
            }
            return cur == D;
        }
        // Determine step direction
        int ddr = (ti - si) / steps;
        int ddc = (tj - sj) / steps;
        int r = si, c = sj;
        for (int step = 0; step <= steps; step++) {
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    int nr = r + di, nc = c + dj;
                    if (nr >= 0 && nr < H && nc >= 0 && nc < W) {
                        cur[nr][nc]++;
                    }
                }
            }
            if (step < steps) {
                r += ddr;
                c += ddc;
            }
        }
        return cur == D;
    };

    // Try all possible start and end positions with constraint
    for (int si = 1; si < H-1; si++) {
        for (int sj = 1; sj < W-1; sj++) {
            for (int ti = 1; ti < H-1; ti++) {
                for (int tj = 1; tj < W-1; tj++) {
                    if (10000 * ti + tj <= 10000 * si + sj) {
                        if (simulate(si, sj, ti, tj)) {
                            cout << si << " " << sj << " " << ti << " " << tj << "\n";
                            return 0;
                        }
                    }
                }
            }
        }
    }

    return 0;
}

