#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;

    vector<string> raw(H);
    for (int i = 0; i < H; ++i) cin >> raw[i];

    // Convert damage states to counts:
    // no damage -> 0
    // minor damage -> 1
    // half-destroyed -> 2
    // destroyed -> 3
    //
    // The statement image/format may use arbitrary symbols, so we support:
    // digits 0..3 directly, or common letters.
    auto conv = [&](char c) -> int {
        if ('0' <= c && c <= '3') return c - '0';
        if (c == '.' || c == 'N' || c == 'n') return 0;
        if (c == 'M' || c == 'm') return 1;
        if (c == 'H' || c == 'h') return 2;
        if (c == 'D' || c == 'd' || c == 'X' || c == 'x') return 3;
        return c - '0'; // fallback for numeric input
    };

    vector<vector<int>> D(H, vector<int>(W));
    for (int i = 0; i < H; ++i)
        for (int j = 0; j < W; ++j)
            D[i][j] = conv(raw[i][j]);

    // Centers can only be on inner cells.
    vector<pair<int,int>> centers;
    for (int i = 1; i <= H - 2; ++i) {
        for (int j = 1; j <= W - 2; ++j) {
            centers.push_back({i, j});
        }
    }

    int N = (int)centers.size();
    if (N == 0) return 0;

    // Build adjacency in 8-neighborhood among possible centers.
    vector<vector<int>> adj(N);
    for (int a = 0; a < N; ++a) {
        auto [i, j] = centers[a];
        for (int b = 0; b < N; ++b) {
            if (a == b) continue;
            auto [ni, nj] = centers[b];
            if (max(abs(i - ni), abs(j - nj)) == 1) {
                adj[a].push_back(b);
            }
        }
    }

    // For each start/end pair, the damage count at each cell equals
    // the number of visited centers whose 3x3 covers that cell.
    // Since no house is completely gone, counts are in {0,1,2,3}.
    //
    // We search all pairs and reconstruct whether there exists a simple path
    // from s to t whose coverage matches D.
    //
    // Let rem[i][j] be remaining required coverage count for each cell.
    // DFS on simple paths with pruning.

    auto inside3 = [&](int ci, int cj, int x, int y) -> bool {
        return abs(ci - x) <= 1 && abs(cj - y) <= 1;
    };

    vector<vector<int>> coverCells(N);
    for (int id = 0; id < N; ++id) {
        auto [ci, cj] = centers[id];
        for (int x = ci - 1; x <= ci + 1; ++x) {
            for (int y = cj - 1; y <= cj + 1; ++y) {
                coverCells[id].push_back(x * W + y);
            }
        }
    }

    auto lex_ok = [&](pair<int,int> s, pair<int,int> t) {
        long long S = 10000LL * s.first + s.second;
        long long T = 10000LL * t.first + t.second;
        return T <= S;
    };

    for (int si = 0; si < N; ++si) {
        for (int ti = 0; ti < N; ++ti) {
            auto s = centers[si];
            auto t = centers[ti];
            if (!lex_ok(s, t)) continue;

            vector<int> rem(H * W);
            for (int i = 0; i < H; ++i)
                for (int j = 0; j < W; ++j)
                    rem[i * W + j] = D[i][j];

            vector<char> used(N, 0);

            // Apply/remove a center's 3x3 effect.
            auto apply = [&](int id, int delta) -> bool {
                for (int p : coverCells[id]) {
                    rem[p] -= delta;
                    if (rem[p] < 0) return false;
                }
                return true;
            };
            auto undo = [&](int id, int delta) {
                for (int p : coverCells[id]) rem[p] += delta;
            };

            // Necessary condition: start and end must each be visited once.
            bool ok = apply(si, 1);
            if (!ok) {
                undo(si, 1);
                continue;
            }
            used[si] = 1;
            if (ti != si) {
                ok = apply(ti, 1);
                if (!ok) {
                    undo(ti, 1);
                    used[si] = 0;
                    continue;
                }
                used[ti] = 1;
            }

            // We need to add some intermediate centers so that:
            // - they form a simple path connecting si to ti
            // - final rem all become 0

            bool found = false;

            function<void(int)> dfs = [&](int cur) {
                if (found) return;

                // If cur == ti and all rem are zero, success.
                if (cur == ti) {
                    bool allzero = true;
                    for (int v : rem) {
                        if (v != 0) {
                            allzero = false;
                            break;
                        }
                    }
                    if (allzero) {
                        found = true;
                        return;
                    }
                }

                // Prune: every positive rem cell must still be coverable by some unvisited
                // center adjacent-reachable in principle; weak prune omitted for simplicity.

                for (int nx : adj[cur]) {
                    if (used[nx]) continue;

                    // Avoid visiting t before finishing path extension unless nx==ti.
                    used[nx] = 1;
                    if (apply(nx, 1)) {
                        dfs(nx);
                    }
                    undo(nx, 1);
                    used[nx] = 0;
                    if (found) return;
                }
            };

            if (si == ti) {
                // Path of length 0 already accounted for.
                bool allzero = true;
                for (int v : rem) if (v != 0) allzero = false;
                if (allzero) found = true;
                if (!found) dfs(si);
            } else {
                // We already applied ti, but path must end there.
                // Build path from si to ti by adding intermediate nodes before ti.
                // So we do DFS from si, but cannot step onto ti again.
                // Easier: temporarily unapply ti, and require DFS path reaches ti, applying on entry.
                undo(ti, 1);
                used[ti] = 0;

                function<void(int)> dfs2 = [&](int cur) {
                    if (found) return;

                    if (cur == ti) {
                        bool allzero = true;
                        for (int v : rem) {
                            if (v != 0) {
                                allzero = false;
                                break;
                            }
                        }
                        if (allzero) found = true;
                        return;
                    }

                    for (int nx : adj[cur]) {
                        if (used[nx]) continue;
                        used[nx] = 1;
                        if (apply(nx, 1)) {
                            dfs2(nx);
                        }
                        undo(nx, 1);
                        used[nx] = 0;
                        if (found) return;
                    }
                };

                dfs2(si);
            }

            if (found) {
                cout << s.first << ' ' << s.second << ' ' << t.first << ' ' << t.second << '\n';
                return 0;
            }

            if (ti != si) {
                // already unapplied in branch above or still applied in same-node branch
                if (used[ti]) {
                    undo(ti, 1);
                    used[ti] = 0;
                }
            }
            undo(si, 1);
            used[si] = 0;
        }
    }

    return 0;
}

import java.util.Scanner;

public class Typhoon {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int H = sc.nextInt();
        int W = sc.nextInt();
        int[][] damage = new int[H][W];
        int[][] counts = new int[H][W];

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                damage[i][j] = sc.nextInt();
                // convert damage to hit count
                counts[i][j] = damage[i][j];
            }
        }

        int start_i = -1, start_j = -1;
        int end_i = -1, end_j = -1;

        // Try all possible center positions
        for (int i = 1; i <= H - 2; i++) {
            for (int j = 1; j <= W - 2; j++) {
                // check if this center could be used
                boolean canUse = true;
                for (int di = -1; di <= 1; di++) {
                    for (int dj = -1; dj <= 1; dj++) {
                        if (counts[i + di][j + dj] <= 0) {
                            canUse = false;
                        }
                    }
                }
                if (canUse) {
                    // Apply: subtract 1 from all 9 cells
                    for (int di = -1; di <= 1; di++) {
                        for (int dj = -1; dj <= 1; dj++) {
                            counts[i + di][j + dj]--;
                        }
                    }
                    // Record position
                    if (start_i == -1) {
                        start_i = i;
                        start_j = j;
                    }
                    end_i = i;
                    end_j = j;
                }
            }
        }

        // Condition: 10000*t_i + t_j <= 10000*s_i + s_j
        // Already satisfied if start is first and end is last in
        // row-major order, so s = start, t = end.
        System.out.println(start_i + " " + start_j + " " + end_i + " " + end_j);
    }
}

