import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    static int H, W;
    static int[][] D;

    static final int[] di = {-1,-1,-1,0,0,1,1,1};
    static final int[] dj = {-1,0,1,-1,1,-1,0,1};

    static boolean insideCenter(int i, int j) {
        return 1 <= i && i <= H - 2 && 1 <= j && j <= W - 2;
    }

    static boolean adjacent8(int a, int b, int c, int d) {
        return Math.max(Math.abs(a - c), Math.abs(b - d)) == 1;
    }

    static boolean checkPair(int si, int sj, int ti, int tj) {
        int[][] cur = new int[H][W];
        ArrayDeque<int[]> q = new ArrayDeque<>();
        boolean[][] vis = new boolean[H][W];

        cur[si][sj] = 1;
        q.add(new int[]{si, sj});
        vis[si][sj] = true;

        while (!q.isEmpty()) {
            int[] v = q.poll();
            int i = v[0], j = v[1];
            int val = cur[i][j];

            if (i == ti && j == tj) continue;

            for (int k = 0; k < 8; k++) {
                int ni = i + di[k], nj = j + dj[k];
                if (!insideCenter(ni, nj)) continue;
                if (!adjacent8(i, j, ni, nj)) continue;

                int nextVal = val + 1;
                if (nextVal > 4) continue; // impossible because no house completely gone

                if (cur[ni][nj] == 0) {
                    cur[ni][nj] = nextVal;
                } else if (cur[ni][nj] != nextVal) {
                    continue;
                }

                if (!vis[ni][nj]) {
                    vis[ni][nj] = true;
                    q.add(new int[]{ni, nj});
                }
            }
        }

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                if (cur[i][j] != D[i][j]) return false;
            }
        }
        return true;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        H = fs.nextInt();
        W = fs.nextInt();

        D = new int[H][W];
        List<int[]> ones = new ArrayList<>();
        List<int[]> fours = new ArrayList<>();

        for (int i = 0; i < H; i++) {
            for (int j = 0; j < W; j++) {
                D[i][j] = fs.nextInt();
