#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAXH 1005
#define MAXW 1005

int H, W;
char S[MAXH][MAXW + 5];
int Dmg[MAXH][MAXW];      // 0..3
int pref[MAXH][MAXW];     // prefix sum of centers existence
int val[MAXH][MAXW];      // reconstructed visitation count for center cells, 0/1

int inside_center(int i, int j) {
    return (1 <= i && i <= H - 2 && 1 <= j && j <= W - 2);
}

int rect_sum(int x1, int y1, int x2, int y2) {
    if (x1 > x2 || y1 > y2) return 0;
    return pref[x2 + 1][y2 + 1] - pref[x1][y2 + 1] - pref[x2 + 1][y1] + pref[x1][y1];
}

int neighbors8_count(int i, int j, int out[8][2]) {
    int cnt = 0;
    for (int di = -1; di <= 1; di++) {
        for (int dj = -1; dj <= 1; dj++) {
            if (di == 0 && dj == 0) continue;
            int ni = i + di, nj = j + dj;
            if (inside_center(ni, nj)) {
                out[cnt][0] = ni;
                out[cnt][1] = nj;
                cnt++;
            }
        }
    }
    return cnt;
}

int main(void) {
    if (scanf("%d %d", &H, &W) != 2) return 0;
    for (int i = 0; i < H; i++) {
        scanf("%s", S[i]);
    }

    // Map damage states to counts:
    // '.' none -> 0
    // 'S' minor -> 1
    // 'M' half-destroyed -> 2
    // 'X' destroyed -> 3
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            char c = S[i][j];
            if (c == '.') Dmg[i][j] = 0;
            else if (c == 'S') Dmg[i][j] = 1;
            else if (c == 'M') Dmg[i][j] = 2;
            else Dmg[i][j] = 3; // 'X'
        }
    }

    // Reconstruct which center cells were visited.
    // A house damage count equals the number of visited centers in its 3x3 neighborhood.
    // For center cells (1..H-2, 1..W-2), each visited at most once because path is simple
    // (if a center repeats, some house would reach damage 4 or more, impossible).
    // Since all counts are <= 3, the visited centers form a simple path.
    //
    // For any center cell (i,j), val[i][j] can be derived greedily using 2D prefix:
    // Dmg[i-1][j-1] = sum of val over centers in [(i-2)..i] x [(j-2)..j]
    // and among these, val[i][j] is the only unknown if processed row-major.
    memset(pref, 0, sizeof(pref));
    for (int i = 1; i <= H - 2; i++) {
        for (int j = 1; j <= W - 2; j++) {
            int x1 = i - 2, y1 = j - 2, x2 = i, y2 = j;
            if (x1 < 1) x1 = 1;
            if (y1 < 1) y1 = 1;
            if (x2 > H - 2) x2 = H - 2;
            if (y2 > W - 2) y2 = W - 2;

            int known = rect_sum(x1, y1, i - 1, j) + rect_sum(i, y1, i, j - 1);
            val[i][j] = Dmg[i - 1][j - 1] - known;
            if (val[i][j] < 0) val[i][j] = 0;
            if (val[i][j] > 1) val[i][j] = 1;

            pref[i + 1][j + 1] = pref[i][j + 1] + pref[i + 1][j] - pref[i][j] + val[i][j];
        }
    }

    // Collect visited centers and degrees in 8-neighbor graph.
    int total = 0;
    int si = -1, sj = -1, ti = -1, tj = -1;
    int endcnt = 0;

    for (int i = 1; i <= H - 2; i++) {
        for (int j = 1; j <= W - 2; j++) {
            if (!val[i][j]) continue;
            total++;
            int deg = 0;
            for (int di = -1; di <= 1; di++) {
                for (int dj = -1; dj <= 1; dj++) {
                    if (di == 0 && dj == 0) continue;
                    int ni = i + di, nj = j + dj;
                    if (inside_center(ni, nj) && val[ni][nj]) deg++;
                }
            }
            if (deg <= 1) {
                endcnt++;
                if (si == -1 || 10000 * i + j > 10000 * si + sj) {
                    si = i; sj = j;
                }
                if (ti == -1 || 10000 * i + j < 10000 * ti + tj) {
                    ti = i; tj = j;
                }
            }
        }
    }

    // If only one visited center, start=end there.
    if (total == 1) {
        for (int i = 1; i <= H - 2; i++) {
            for (int j = 1; j <= W - 2; j++) {
                if (val[i][j]) {
                    printf("%d %d %d %d\n", i, j, i, j);
                    return 0;
                }
            }
        }
    }

    // For a simple path, there are two endpoints.
    // Need output satisfying 10000*t_i+t_j <= 10000*s_i+s_j.
    // So choose lexicographically larger endpoint as s, smaller as t.
    printf("%d %d %d %d\n", si, sj, ti, tj);
    return 0;
}
